def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)
    with io.open(os.path.join(root, SEEDER_PATH), encoding="utf-8") as f:
        seeder = f.read()

    if "advanced_accounts" in data:
        print("Already applied. Nothing to do.")
        return
    if '"3.119.0"' not in init:
        sys.exit("ABORT: not at v3.119.0.")

    old_order = 'ORDER = ["chart_gl", "journal_entries", "banking", "ar_ap_chair", "tax_compliance", "dimensions", "close_statements"]'
    new_order = 'ORDER = ["chart_gl", "journal_entries", "banking", "ar_ap_chair", "tax_compliance", "dimensions", "close_statements", "advanced_accounts"]'
    if seeder.count(old_order) != 1:
        sys.exit(f"ABORT: seeder ORDER anchor not found exactly once ({seeder.count(old_order)}).")

    problems = []
    if len(LESSONS) != 9:
        problems.append(f"  {len(LESSONS)} lessons (want 9)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"Accounts 8: 9 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["advanced_accounts"] = {
        "title": "Accounts 8 — Advanced Accounts: Settings, Controls & Structure",
        "desc": "The structural layer: Accounts Settings as the constitution, fiscal years and the multi-company frontier, the four finance authorities, the finance calendar, the handover test, internal controls assembled with the fraud triangle, the professional ecosystem, and the eighth law — closing the ZhiftERP Accounts Professional track and the academy's four-track foundation.",
        "lessons": LESSONS,
        "questions": bank,
    }
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, SEEDER_PATH), "w", encoding="utf-8") as f:
        f.write(seeder.replace(old_order, new_order, 1))
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.119.0"', '"3.120.0"'))
    print("  data: Accounts 8 appended; seeder ORDER extended — TRACK COMPLETE, FOUNDATION COMPLETE")
    print("wrote __version__ -> 3.120.0")


if __name__ == "__main__":
    main()
